update public.questions set clue_refs = '[[{"ref": "Exodus 4:14", "text": "And the anger of the LORD was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart."}], [{"ref": "Exodus 7:2", "text": "Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land."}], [{"ref": "Exodus 32:1-4", "text": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him. And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me. And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron. And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy …"}], [{"ref": "Numbers 17:8", "text": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}]]'::jsonb, updated_at = now() where id = 'who-aaron' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 25:3", "text": "Now the name of the man was Nabal; and the name of his wife Abigail: and she was a woman of good understanding, and of a beautiful countenance: but the man was churlish and evil in his doings; and he was of the house of Caleb."}], [{"ref": "1 Samuel 25:18", "text": "Then Abigail made haste, and took two hundred loaves, and two bottles of wine, and five sheep ready dressed, and five measures of parched corn, and an hundred clusters of raisins, and two hundred cakes of figs, and laid them on asses."}], [{"ref": "1 Samuel 25:33", "text": "And blessed be thy advice, and blessed be thou, which hast kept me this day from coming to shed blood, and from avenging myself with mine own hand."}], [{"ref": "1 Samuel 25:38-39", "text": "And it came to pass about ten days after, that the LORD smote Nabal, that he died. And when David heard that Nabal was dead, he said, Blessed be the LORD, that hath pleaded the cause of my reproach from the hand of Nabal, and hath kept his servant from evil: for the LORD hath returned the wickedness of Nabal upon his own head. And David sent and communed with Abigail, to take her to him to wife."}, {"ref": "1 Samuel 25:42", "text": "And Abigail hasted, and arose, and rode upon an ass, with five damsels of hers that went after her; and she went after the messengers of David, and became his wife."}]]'::jsonb, updated_at = now() where id = 'who-abigail' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 11:31", "text": "And Terah took Abram his son, and Lot the son of Haran his son’s son, and Sarai his daughter in law, his son Abram’s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there."}], [{"ref": "Genesis 17:5", "text": "Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee."}], [{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 22:1-2", "text": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}]]'::jsonb, updated_at = now() where id = 'who-abraham' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 3:3", "text": "And his second, Chileab, of Abigail the wife of Nabal the Carmelite; and the third, Absalom the son of Maacah the daughter of Talmai king of Geshur;"}], [{"ref": "2 Samuel 15:6", "text": "And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel."}], [{"ref": "2 Samuel 15:10-12", "text": "But Absalom sent spies throughout all the tribes of Israel, saying, As soon as ye hear the sound of the trumpet, then ye shall say, Absalom reigneth in Hebron. And with Absalom went two hundred men out of Jerusalem, that were called; and they went in their simplicity, and they knew not any thing. And Absalom sent for Ahithophel the Gilonite, David’s counsellor, from his city, even from Giloh, while he offered sacrifices. And the conspiracy was strong; for the people increased continually with Absalom."}], [{"ref": "2 Samuel 18:9", "text": "And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away."}]]'::jsonb, updated_at = now() where id = 'who-absalom' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 2:7", "text": "And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul."}], [{"ref": "Genesis 2:20", "text": "And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him."}], [{"ref": "Genesis 2:15", "text": "And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it."}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb, updated_at = now() where id = 'who-adam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 16:29", "text": "And in the thirty and eighth year of Asa king of Judah began Ahab the son of Omri to reign over Israel: and Ahab the son of Omri reigned over Israel in Samaria twenty and two years."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 18:17", "text": "And it came to pass, when Ahab saw Elijah, that Ahab said unto him, Art thou he that troubleth Israel?"}], [{"ref": "1 Kings 21:2", "text": "And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money."}]]'::jsonb, updated_at = now() where id = 'who-ahab' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Amos 1:1", "text": "The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 5:24", "text": "But let judgment run down as waters, and righteousness as a mighty stream."}]]'::jsonb, updated_at = now() where id = 'who-amos' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:40", "text": "One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother."}], [{"ref": "John 1:41-42", "text": "He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ. And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone."}], [{"ref": "John 6:8-9", "text": "One of his disciples, Andrew, Simon Peter’s brother, saith unto him, There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"}]]'::jsonb, updated_at = now() where id = 'who-andrew' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:36", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;"}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:27", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law,"}, {"ref": "Luke 2:36-38", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity; And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day. And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem."}]]'::jsonb, updated_at = now() where id = 'who-anna' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}], [{"ref": "1 Corinthians 3:6", "text": "I have planted, Apollos watered; but God gave the increase."}]]'::jsonb, updated_at = now() where id = 'who-apollos' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Joshua 13:22", "text": "Balaam also the son of Beor, the soothsayer, did the children of Israel slay with the sword among them that were slain by them."}], [{"ref": "Numbers 22:4-6", "text": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time. He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me: Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou …"}], [{"ref": "Numbers 22:31", "text": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}], [{"ref": "Numbers 22:28", "text": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}]]'::jsonb, updated_at = now() where id = 'who-balaam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 4:36", "text": "And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,"}], [{"ref": "Acts 4:37", "text": "Having land, sold it, and brought the money, and laid it at the apostles’ feet."}], [{"ref": "Acts 9:26-27", "text": "And when Saul was come to Jerusalem, he assayed to join himself to the disciples: but they were all afraid of him, and believed not that he was a disciple. But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus."}], [{"ref": "Acts 13:2-4", "text": "As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them. And when they had fasted and prayed, and laid their hands on them, they sent them away. So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus."}]]'::jsonb, updated_at = now() where id = 'who-barnabas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}], [{"ref": "2 Samuel 11:2", "text": "And it came to pass in an eveningtide, that David arose from off his bed, and walked upon the roof of the king’s house: and from the roof he saw a woman washing herself; and the woman was very beautiful to look upon."}], [{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 2:19", "text": "Bath-sheba therefore went unto king Solomon, to speak unto him for Adonijah. And the king rose up to meet her, and bowed himself unto her, and sat down on his throne, and caused a seat to be set for the king’s mother; and she sat on his right hand."}]]'::jsonb, updated_at = now() where id = 'who-bathsheba' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ruth 2:1", "text": "And Naomi had a kinsman of her husband’s, a mighty man of wealth, of the family of Elimelech; and his name was Boaz."}, {"ref": "Ruth 2:4", "text": "And, behold, Boaz came from Beth-lehem, and said unto the reapers, The LORD be with you. And they answered him, The LORD bless thee."}], [{"ref": "Ruth 2:6", "text": "And the servant that was set over the reapers answered and said, It is the Moabitish damsel that came back with Naomi out of the country of Moab:"}, {"ref": "Ruth 2:8", "text": "Then said Boaz unto Ruth, Hearest thou not, my daughter? Go not to glean in another field, neither go from hence, but abide here fast by my maidens:"}], [{"ref": "Ruth 4:9-10", "text": "And Boaz said unto the elders, and unto all the people, Ye are witnesses this day, that I have bought all that was Elimelech’s, and all that was Chilion’s and Mahlon’s, of the hand of Naomi. Moreover Ruth the Moabitess, the wife of Mahlon, have I purchased to be my wife, to raise up the name of the dead upon his inheritance, that the name of the dead be not cut off from among his brethren, and from the gate of his place: ye are witnesses this day."}], [{"ref": "Ruth 4:13", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son."}]]'::jsonb, updated_at = now() where id = 'who-boaz' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:49", "text": "And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all,"}], [{"ref": "John 11:50", "text": "Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not."}], [{"ref": "John 18:13", "text": "And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}], [{"ref": "John 18:24", "text": "Now Annas had sent him bound unto Caiaphas the high priest."}]]'::jsonb, updated_at = now() where id = 'who-caiaphas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:5", "text": "But unto Cain and to his offering he had not respect. And Cain was very wroth, and his countenance fell."}], [{"ref": "Genesis 4:9", "text": "And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?"}], [{"ref": "Genesis 4:15", "text": "And the LORD said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the LORD set a mark upon Cain, lest any finding him should kill him."}]]'::jsonb, updated_at = now() where id = 'who-cain' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Numbers 13:6", "text": "Of the tribe of Judah, Caleb the son of Jephunneh."}], [{"ref": "Numbers 14:6-9", "text": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes: And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land. If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey. Only rebel not ye against the LORD, neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not."}], [{"ref": "Joshua 14:10", "text": "And now, behold, the LORD hath kept me alive, as he said, these forty and five years, even since the LORD spake this word unto Moses, while the children of Israel wandered in the wilderness: and now, lo, I am this day fourscore and five years old."}], [{"ref": "Joshua 14:12-13", "text": "Now therefore give me this mountain, whereof the LORD spake in that day; for thou heardest in that day how the Anakims were there, and that the cities were great and fenced: if so be the LORD will be with me, then I shall be able to drive them out, as the LORD said. And Joshua blessed him, and gave unto Caleb the son of Jephunneh Hebron for an inheritance."}]]'::jsonb, updated_at = now() where id = 'who-caleb' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 10:1", "text": "There was a certain man in Cæsarea called Cornelius, a centurion of the band called the Italian band,"}], [{"ref": "Acts 10:2", "text": "A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway."}], [{"ref": "Acts 10:3-5", "text": "He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius. And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God. And now send men to Joppa, and call for one Simon, whose surname is Peter:"}], [{"ref": "Acts 10:24", "text": "And the morrow after they entered into Cæsarea. And Cornelius waited for them, and had called together his kinsmen and near friends."}, {"ref": "Acts 10:44", "text": "While Peter yet spake these words, the Holy Ghost fell on all them which heard the word."}]]'::jsonb, updated_at = now() where id = 'who-cornelius' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Daniel 1:1-6", "text": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it. And the Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God: which he carried into the land of Shinar to the house of his god; and he brought the vessels into the treasure house of his god. And the king spake unto Ashpenaz the master of his eunuchs, that he should bring certain of the children of Israel, and of the king’s seed, and of the princes; Children in whom was no blemish, but well favoured, and skilful in all wisdom, and cunning in knowledge, and understanding science, and such as had ability in them to stand in the …"}], [{"ref": "Daniel 1:8", "text": "But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."}], [{"ref": "Daniel 5:25-28", "text": "And this is the writing that was written, MENE, MENE, TEKEL, UPHARSIN. This is the interpretation of the thing: MENE; God hath numbered thy kingdom, and finished it. TEKEL; Thou art weighed in the balances, and art found wanting. PERES; Thy kingdom is divided, and given to the Medes and Persians."}], [{"ref": "Daniel 6:22-23", "text": "My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt. Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God."}]]'::jsonb, updated_at = now() where id = 'who-daniel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 16:11", "text": "And Samuel said unto Jesse, Are here all thy children? And he said, There remaineth yet the youngest, and, behold, he keepeth the sheep. And Samuel said unto Jesse, Send and fetch him: for we will not sit down till he come hither."}], [{"ref": "1 Samuel 16:23", "text": "And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him."}], [{"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}], [{"ref": "2 Samuel 5:3", "text": "So all the elders of Israel came to the king to Hebron; and king David made a league with them in Hebron before the LORD: and they anointed David king over Israel."}]]'::jsonb, updated_at = now() where id = 'who-david' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 4:4", "text": "And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time."}], [{"ref": "Judges 4:5", "text": "And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment."}], [{"ref": "Judges 4:6-7", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun? And I will draw unto thee to the river Kishon Sisera, the captain of Jabin’s army, with his chariots and his multitude; and I will deliver him into thine hand."}], [{"ref": "Judges 5:1", "text": "Then sang Deborah and Barak the son of Abinoam on that day, saying,"}]]'::jsonb, updated_at = now() where id = 'who-deborah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 16:4", "text": "And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."}], [{"ref": "Judges 16:5", "text": "And the lords of the Philistines came up unto her, and said unto her, Entice him, and see wherein his great strength lieth, and by what means we may prevail against him, that we may bind him to afflict him: and we will give thee every one of us eleven hundred pieces of silver."}], [{"ref": "Judges 16:6", "text": "And Delilah said to Samson, Tell me, I pray thee, wherein thy great strength lieth, and wherewith thou mightest be bound to afflict thee."}], [{"ref": "Judges 16:19", "text": "And she made him sleep upon her knees; and she called for a man, and she caused him to shave off the seven locks of his head; and she began to afflict him, and his strength went from him."}]]'::jsonb, updated_at = now() where id = 'who-delilah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:39", "text": "Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them."}], [{"ref": "Acts 9:40", "text": "But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up."}]]'::jsonb, updated_at = now() where id = 'who-dorcas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD."}], [{"ref": "1 Samuel 1:13-14", "text": "Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken. And Eli said unto her, How long wilt thou be drunken? put away thy wine from thee."}], [{"ref": "1 Samuel 1:3", "text": "And this man went up out of his city yearly to worship and to sacrifice unto the LORD of hosts in Shiloh. And the two sons of Eli, Hophni and Phinehas, the priests of the LORD, were there."}, {"ref": "1 Samuel 2:12", "text": "Now the sons of Eli were sons of Belial; they knew not the LORD."}], [{"ref": "1 Samuel 4:17-18", "text": "And the messenger answered and said, Israel is fled before the Philistines, and there hath been also a great slaughter among the people, and thy two sons also, Hophni and Phinehas, are dead, and the ark of God is taken. And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."}]]'::jsonb, updated_at = now() where id = 'who-eli' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 17:1", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word."}], [{"ref": "1 Kings 17:1-6", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the …"}], [{"ref": "1 Kings 18:19-24", "text": "Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table. So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel. And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word. Then said Elijah unto the people, I, even I only, remain a prophet of the LORD; but Baal’s prophets are four hundred and fifty men. Let them therefore give us two bullocks; and let them choose one bullock for themselves, …"}], [{"ref": "2 Kings 2:11", "text": "And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven."}]]'::jsonb, updated_at = now() where id = 'who-elijah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}], [{"ref": "Luke 1:7", "text": "And they had no child, because that Elisabeth was barren, and they both were now well stricken in years."}], [{"ref": "Luke 1:41", "text": "And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:"}], [{"ref": "Luke 1:57-60", "text": "Now Elisabeth’s full time came that she should be delivered; and she brought forth a son. And her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her. And it came to pass, that on the eighth day they came to circumcise the child; and they called him Zacharias, after the name of his father. And his mother answered and said, Not so; but he shall be called John."}]]'::jsonb, updated_at = now() where id = 'who-elisabeth' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 19:19", "text": "So he departed thence, and found Elisha the son of Shaphat, who was plowing with twelve yoke of oxen before him, and he with the twelfth: and Elijah passed by him, and cast his mantle upon him."}], [{"ref": "2 Kings 2:9", "text": "And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."}], [{"ref": "2 Kings 2:13", "text": "He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;"}], [{"ref": "2 Kings 5:10", "text": "And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean."}]]'::jsonb, updated_at = now() where id = 'who-elisha' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 5:22", "text": "And Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters:"}], [{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:24", "text": "And Enoch walked with God: and he was not; for God took him."}], [{"ref": "Hebrews 11:5", "text": "By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God."}]]'::jsonb, updated_at = now() where id = 'who-enoch' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 25:27", "text": "And the boys grew: and Esau was a cunning hunter, a man of the field; and Jacob was a plain man, dwelling in tents."}], [{"ref": "Genesis 25:25", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 36:1", "text": "Now these are the generations of Esau, who is Edom."}]]'::jsonb, updated_at = now() where id = 'who-esau' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Esther 2:7", "text": "And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}], [{"ref": "Esther 1:3", "text": "In the third year of his reign, he made a feast unto all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him:"}, {"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}], [{"ref": "Esther 4:16", "text": "Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish."}], [{"ref": "Esther 9:22", "text": "As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor."}, {"ref": "Esther 9:26-28", "text": "Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them, The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their appointed time every year; And that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed."}]]'::jsonb, updated_at = now() where id = 'who-esther' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 3:1", "text": "Now the serpent was more subtil than any beast of the field which the LORD God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?"}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb, updated_at = now() where id = 'who-eve' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ezekiel 1:1-3", "text": "Now it came to pass in the thirtieth year, in the fourth month, in the fifth day of the month, as I was among the captives by the river of Chebar, that the heavens were opened, and I saw visions of God. In the fifth day of the month, which was the fifth year of king Jehoiachin’s captivity, The word of the LORD came expressly unto Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the river Chebar; and the hand of the LORD was there upon him."}], [{"ref": "Ezekiel 1:18", "text": "As for their rings, they were so high that they were dreadful; and their rings were full of eyes round about them four."}], [{"ref": "Ezekiel 4:4-6", "text": "Lie thou also upon thy left side, and lay the iniquity of the house of Israel upon it: according to the number of the days that thou shalt lie upon it thou shalt bear their iniquity. For I have laid upon thee the years of their iniquity, according to the number of the days, three hundred and ninety days: so shalt thou bear the iniquity of the house of Israel. And when thou hast accomplished them, lie again on thy right side, and thou shalt bear the iniquity of the house of Judah forty days: I have appointed thee each day for a year."}], [{"ref": "Ezekiel 37:4", "text": "Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-ezekiel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ezra 7:6", "text": "This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}, {"ref": "Ezra 7:11", "text": "Now this is the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, even a scribe of the words of the commandments of the LORD, and of his statutes to Israel."}], [{"ref": "Ezra 7:1-6", "text": "Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah, The son of Shallum, the son of Zadok, the son of Ahitub, The son of Amariah, the son of Azariah, the son of Meraioth, The son of Zerahiah, the son of Uzzi, the son of Bukki, The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest: This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}], [{"ref": "Nehemiah 8:2-3", "text": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month. And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}], [{"ref": "Nehemiah 8:4", "text": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}]]'::jsonb, updated_at = now() where id = 'who-ezra' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:38", "text": "And now I say unto you, Refrain from these men, and let them alone: for if this counsel or this work be of men, it will come to nought:"}], [{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}]]'::jsonb, updated_at = now() where id = 'who-gamaliel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 6:11-12", "text": "And there came an angel of the LORD, and sat under an oak which was in Ophrah, that pertained unto Joash the Abi-ezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites. And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour."}], [{"ref": "Judges 6:36-40", "text": "And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said, Behold, I will put a fleece of wool in the floor; and if the dew be on the fleece only, and it be dry upon all the earth beside, then shall I know that thou wilt save Israel by mine hand, as thou hast said. And it was so: for he rose up early on the morrow, and thrust the fleece together, and wringed the dew out of the fleece, a bowl full of water. And Gideon said unto God, Let not thine anger be hot against me, and I will speak but this once: let me prove, I pray thee, but this once with the fleece; let it now be dry only upon the fleece, and upon all the ground let there be dew. And God did so that night: …"}], [{"ref": "Judges 7:7", "text": "And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place."}], [{"ref": "Judges 7:16", "text": "And he divided the three hundred men into three companies, and he put a trumpet in every man’s hand, with empty pitchers, and lamps within the pitchers."}]]'::jsonb, updated_at = now() where id = 'who-gideon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:15", "text": "But David went and returned from Saul to feed his father’s sheep at Beth-lehem."}, {"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}]]'::jsonb, updated_at = now() where id = 'who-goliath' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:1-2", "text": "Now there was a certain man of Ramathaim-zophim, of mount Ephraim, and his name was Elkanah, the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephrathite: And he had two wives; the name of the one was Hannah, and the name of the other Peninnah: and Peninnah had children, but Hannah had no children."}], [{"ref": "1 Samuel 1:9-13", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head. And it came to pass, as she continued praying before the LORD, that Eli marked her mouth. Now Hannah, she spake in her heart; only her lips moved, but her voice was …"}], [{"ref": "1 Samuel 1:11", "text": "And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}], [{"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-hannah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 2:1", "text": "Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,"}], [{"ref": "Matthew 2:2-3", "text": "Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him. When Herod the king had heard these things, he was troubled, and all Jerusalem with him."}], [{"ref": "Matthew 2:8", "text": "And he sent them to Bethlehem, and said, Go and search diligently for the young child; and when ye have found him, bring me word again, that I may come and worship him also."}], [{"ref": "Matthew 2:16", "text": "Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men."}]]'::jsonb, updated_at = now() where id = 'who-herod' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 18:1", "text": "Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign."}], [{"ref": "2 Kings 18:4", "text": "He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan."}], [{"ref": "Isaiah 38:1", "text": "In those days was Hezekiah sick unto death. And Isaiah the prophet the son of Amoz came unto him, and said unto him, Thus saith the LORD, Set thine house in order: for thou shalt die, and not live."}], [{"ref": "Isaiah 38:5", "text": "Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years."}]]'::jsonb, updated_at = now() where id = 'who-hezekiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Hosea 1:1", "text": "The word of the LORD that came unto Hosea, the son of Beeri, in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah, and in the days of Jeroboam the son of Joash, king of Israel."}], [{"ref": "Hosea 1:3", "text": "So he went and took Gomer the daughter of Diblaim; which conceived, and bare him a son."}], [{"ref": "Hosea 1:8-9", "text": "Now when she had weaned Lo-ruhamah, she conceived, and bare a son. Then said God, Call his name Lo-ammi: for ye are not my people, and I will not be your God."}], [{"ref": "Hosea 3:2", "text": "So I bought her to me for fifteen pieces of silver, and for an homer of barley, and an half homer of barley:"}]]'::jsonb, updated_at = now() where id = 'who-hosea' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 21:5", "text": "And Abraham was an hundred years old, when his son Isaac was born unto him."}], [{"ref": "Genesis 22:2", "text": "And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}, {"ref": "Genesis 22:9", "text": "And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood."}], [{"ref": "Genesis 25:25-26", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau. And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}]]'::jsonb, updated_at = now() where id = 'who-isaac' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Isaiah 6:1", "text": "In the year that king Uzziah died I saw also the Lord sitting upon a throne, high and lifted up, and his train filled the temple."}], [{"ref": "Isaiah 6:6-7", "text": "Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar: And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged."}], [{"ref": "Isaiah 6:8", "text": "Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me."}], [{"ref": "Isaiah 7:14", "text": "Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel."}]]'::jsonb, updated_at = now() where id = 'who-isaiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 25:26", "text": "And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 28:12", "text": "And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it."}], [{"ref": "Genesis 35:10", "text": "And God said unto him, Thy name is Jacob: thy name shall not be called any more Jacob, but Israel shall be thy name: and he called his name Israel."}]]'::jsonb, updated_at = now() where id = 'who-jacob' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:19", "text": "And he said unto her, Give me, I pray thee, a little water to drink; for I am thirsty. And she opened a bottle of milk, and gave him drink, and covered him."}], [{"ref": "Judges 4:21", "text": "Then Jael Heber’s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died."}]]'::jsonb, updated_at = now() where id = 'who-jael' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Jeremiah 1:5", "text": "Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations."}], [{"ref": "Jeremiah 1:6", "text": "Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child."}], [{"ref": "Jeremiah 38:6", "text": "Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that was in the court of the prison: and they let down Jeremiah with cords. And in the dungeon there was no water, but mire: so Jeremiah sunk in the mire."}], [{"ref": "Jeremiah 36:4", "text": "Then Jeremiah called Baruch the son of Neriah: and Baruch wrote from the mouth of Jeremiah all the words of the LORD, which he had spoken unto him, upon a roll of a book."}]]'::jsonb, updated_at = now() where id = 'who-jeremiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:1", "text": "When Jethro, the priest of Midian, Moses’ father in law, heard of all that God had done for Moses, and for Israel his people, and that the LORD had brought Israel out of Egypt;"}], [{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:17-22", "text": "And Moses’ father in law said unto him, The thing that thou doest is not good. Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone. Hearken now unto my voice, I will give thee counsel, and God shall be with thee: Be thou for the people to God-ward, that thou mayest bring the causes unto God: And thou shalt teach them ordinances and laws, and shalt shew them the way wherein they must walk, and the work that they must do. Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and …"}]]'::jsonb, updated_at = now() where id = 'who-jethro' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 19:1-2", "text": "And Ahab told Jezebel all that Elijah had done, and withal how he had slain all the prophets with the sword. Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time."}], [{"ref": "1 Kings 21:7-15", "text": "And Jezebel his wife said unto him, Dost thou now govern the kingdom of Israel? arise, and eat bread, and let thine heart be merry: I will give thee the vineyard of Naboth the Jezreelite. So she wrote letters in Ahab’s name, and sealed them with his seal, and sent the letters unto the elders and to the nobles that were in his city, dwelling with Naboth. And she wrote in the letters, saying, Proclaim a fast, and set Naboth on high among the people: And set two men, sons of Belial, before him, to bear witness against him, saying, Thou didst blaspheme God and the king. And then carry him out, and stone him, that he may die. And the men of his city, even the elders and the nobles who were the …"}]]'::jsonb, updated_at = now() where id = 'who-jezebel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:13-19", "text": "And there was a day when his sons and his daughters were eating and drinking wine in their eldest brother’s house: And there came a messenger unto Job, and said, The oxen were plowing, and the asses feeding beside them: And the Sabeans fell upon them, and took them away; yea, they have slain the servants with the edge of the sword; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The fire of God is fallen from heaven, and hath burned up the sheep, and the servants, and consumed them; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The Chaldeans made out three bands, and fell upon …"}], [{"ref": "Job 1:21", "text": "And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD."}]]'::jsonb, updated_at = now() where id = 'who-job' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Mark 3:17", "text": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}], [{"ref": "John 21:20", "text": "Then Peter, turning about, seeth the disciple whom Jesus loved following; which also leaned on his breast at supper, and said, Lord, which is he that betrayeth thee?"}], [{"ref": "Revelation 1:9", "text": "I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ."}]]'::jsonb, updated_at = now() where id = 'who-john_apostle' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}, {"ref": "Luke 1:13", "text": "But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Mark 1:9", "text": "And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan."}]]'::jsonb, updated_at = now() where id = 'who-john_baptist' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 14:25", "text": "He restored the coast of Israel from the entering of Hamath unto the sea of the plain, according to the word of the LORD God of Israel, which he spake by the hand of his servant Jonah, the son of Amittai, the prophet, which was of Gath-hepher."}], [{"ref": "Jonah 1:3", "text": "But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD."}], [{"ref": "Jonah 1:17", "text": "Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights."}], [{"ref": "Jonah 3:10", "text": "And God saw their works, that they turned from their evil way; and God repented of the evil, that he had said that he would do unto them; and he did it not."}, {"ref": "Jonah 4:1", "text": "But it displeased Jonah exceedingly, and he was very angry."}]]'::jsonb, updated_at = now() where id = 'who-jonah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 14:1", "text": "Now it came to pass upon a day, that Jonathan the son of Saul said unto the young man that bare his armour, Come, and let us go over to the Philistines’ garrison, that is on the other side. But he told not his father."}], [{"ref": "1 Samuel 14:13", "text": "And Jonathan climbed up upon his hands and upon his feet, and his armourbearer after him: and they fell before Jonathan; and his armourbearer slew after him."}], [{"ref": "1 Samuel 18:1", "text": "And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul."}], [{"ref": "1 Samuel 20:20-22", "text": "And I will shoot three arrows on the side thereof, as though I shot at a mark. And, behold, I will send a lad, saying, Go, find out the arrows. If I expressly say unto the lad, Behold, the arrows are on this side of thee, take them; then come thou: for there is peace to thee, and no hurt; as the LORD liveth. But if I say thus unto the young man, Behold, the arrows are beyond thee; go thy way: for the LORD hath sent thee away."}, {"ref": "1 Samuel 20:36-37", "text": "And he said unto his lad, Run, find out now the arrows which I shoot. And as the lad ran, he shot an arrow beyond him. And when the lad was come to the place of the arrow which Jonathan had shot, Jonathan cried after the lad, and said, Is not the arrow beyond thee?"}]]'::jsonb, updated_at = now() where id = 'who-jonathan' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 37:3", "text": "Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."}], [{"ref": "Genesis 37:26-28", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content. Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt."}], [{"ref": "Genesis 41:25", "text": "And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do."}], [{"ref": "Genesis 41:41", "text": "And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt."}]]'::jsonb, updated_at = now() where id = 'who-joseph' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:4", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:)"}], [{"ref": "Matthew 1:20", "text": "But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost."}], [{"ref": "Matthew 2:14", "text": "When he arose, he took the young child and his mother by night, and departed into Egypt:"}], [{"ref": "Matthew 13:55", "text": "Is not this the carpenter’s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?"}]]'::jsonb, updated_at = now() where id = 'who-joseph_husband' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Numbers 13:2-16", "text": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them. And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel. And these were their names: of the tribe of Reuben, Shammua the son of Zaccur. Of the tribe of Simeon, Shaphat the son of Hori. Of the tribe of Judah, Caleb the son of Jephunneh. Of the tribe of Issachar, Igal the son of Joseph. …"}], [{"ref": "Joshua 1:1-2", "text": "Now after the death of Moses the servant of the LORD it came to pass, that the LORD spake unto Joshua the son of Nun, Moses’ minister, saying, Moses my servant is dead; now therefore arise, go over this Jordan, thou, and all this people, unto the land which I do give to them, even to the children of Israel."}], [{"ref": "Joshua 6:16", "text": "And it came to pass at the seventh time, when the priests blew with the trumpets, Joshua said unto the people, Shout; for the LORD hath given you the city."}, {"ref": "Joshua 6:20", "text": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}], [{"ref": "Joshua 24:15", "text": "And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."}]]'::jsonb, updated_at = now() where id = 'who-joshua' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 22:1", "text": "Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath."}], [{"ref": "2 Kings 22:8", "text": "And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it."}], [{"ref": "2 Kings 22:11", "text": "And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes."}], [{"ref": "2 Kings 23:21-23", "text": "And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant. Surely there was not holden such a passover from the days of the judges that judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah; But in the eighteenth year of king Josiah, wherein this passover was holden to the LORD in Jerusalem."}]]'::jsonb, updated_at = now() where id = 'who-josiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 26:14", "text": "Then one of the twelve, called Judas Iscariot, went unto the chief priests,"}], [{"ref": "John 12:4-6", "text": "Then saith one of his disciples, Judas Iscariot, Simon’s son, which should betray him, Why was not this ointment sold for three hundred pence, and given to the poor? This he said, not that he cared for the poor; but because he was a thief, and had the bag, and bare what was put therein."}], [{"ref": "Matthew 26:15", "text": "And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver."}], [{"ref": "Matthew 26:48-49", "text": "Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast. And forthwith he came to Jesus, and said, Hail, master; and kissed him."}]]'::jsonb, updated_at = now() where id = 'who-judas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:1", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha."}], [{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "John 11:34-35", "text": "And said, Where have ye laid him? They said unto him, Lord, come and see. Jesus wept."}, {"ref": "John 11:38", "text": "Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it."}], [{"ref": "John 11:43-44", "text": "And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go."}]]'::jsonb, updated_at = now() where id = 'who-lazarus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 12:5", "text": "And Abram took Sarai his wife, and Lot his brother’s son, and all their substance that they had gathered, and the souls that they had gotten in Haran; and they went forth to go into the land of Canaan; and into the land of Canaan they came."}], [{"ref": "Genesis 13:11", "text": "Then Lot chose him all the plain of Jordan; and Lot journeyed east: and they separated themselves the one from the other."}], [{"ref": "Genesis 19:1-3", "text": "And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground; And he said, Behold now, my lords, turn in, I pray you, into your servant’s house, and tarry all night, and wash your feet, and ye shall rise up early, and go on your ways. And they said, Nay; but we will abide in the street all night. And he pressed upon them greatly; and they turned in unto him, and entered into his house; and he made them a feast, and did bake unleavened bread, and they did eat."}], [{"ref": "Genesis 19:26", "text": "But his wife looked back from behind him, and she became a pillar of salt."}]]'::jsonb, updated_at = now() where id = 'who-lot' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:12-14", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days. And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither. And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:15", "text": "And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us."}]]'::jsonb, updated_at = now() where id = 'who-lydia' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "Luke 10:40", "text": "But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me."}], [{"ref": "Luke 10:42", "text": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}], [{"ref": "Luke 10:38", "text": "Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house."}]]'::jsonb, updated_at = now() where id = 'who-martha' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:27", "text": "To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 2:4-7", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:) To be taxed with Mary his espoused wife, being great with child. And so it was, that, while they were there, the days were accomplished that she should be delivered. And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."}, {"ref": "Luke 2:21", "text": "And when eight days were accomplished for the circumcising of the child, his name was called JESUS, which was so named of the angel before he was conceived in the womb."}]]'::jsonb, updated_at = now() where id = 'who-mary' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 8:2", "text": "And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,"}], [{"ref": "John 19:25", "text": "Now there stood by the cross of Jesus his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene."}], [{"ref": "John 20:1", "text": "The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre."}], [{"ref": "John 20:15", "text": "Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away."}]]'::jsonb, updated_at = now() where id = 'who-mary_magdalene' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 10:3", "text": "Philip, and Bartholomew; Thomas, and Matthew the publican; James the son of Alphaeus, and Lebbaeus, whose surname was Thaddaeus;"}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9-10", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him. And it came to pass, as Jesus sat at meat in the house, behold, many publicans and sinners came and sat down with him and his disciples."}]]'::jsonb, updated_at = now() where id = 'who-matthew' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:17-18", "text": "And the king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer, and of the kings that were with him, at the valley of Shaveh, which is the king’s dale. And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Hebrews 7:2", "text": "To whom also Abraham gave a tenth part of all; first being by interpretation King of righteousness, and after that also King of Salem, which is, King of peace;"}]]'::jsonb, updated_at = now() where id = 'who-melchizedek' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}, {"ref": "Genesis 5:28-29", "text": "And Lamech lived an hundred eighty and two years, and begat a son: And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which the LORD hath cursed."}], [{"ref": "Genesis 5:27", "text": "And all the days of Methuselah were nine hundred sixty and nine years: and he died."}]]'::jsonb, updated_at = now() where id = 'who-methuselah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 2:3-4", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink. And his sister stood afar off, to wit what would be done to him."}, {"ref": "Numbers 26:59", "text": "And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Numbers 12:10", "text": "And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."}, {"ref": "Numbers 12:14-15", "text": "And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again. And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again."}]]'::jsonb, updated_at = now() where id = 'who-miriam' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Exodus 2:3", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."}], [{"ref": "Exodus 2:10", "text": "And the child grew, and she brought him unto Pharaoh’s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water."}], [{"ref": "Exodus 3:2", "text": "And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed."}], [{"ref": "Acts 7:36", "text": "He brought them out, after that he had shewed wonders and signs in the land of Egypt, and in the Red sea, and in the wilderness forty years."}]]'::jsonb, updated_at = now() where id = 'who-moses' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:2-3", "text": "And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naaman’s wife. And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy."}], [{"ref": "2 Kings 5:14", "text": "Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."}]]'::jsonb, updated_at = now() where id = 'who-naaman' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 7:2", "text": "That the king said unto Nathan the prophet, See now, I dwell in an house of cedar, but the ark of God dwelleth within curtains."}], [{"ref": "2 Samuel 7:4-5", "text": "And it came to pass that night, that the word of the LORD came unto Nathan, saying, Go and tell my servant David, Thus saith the LORD, Shalt thou build me an house for me to dwell in?"}, {"ref": "2 Samuel 7:12-13", "text": "And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom. He shall build an house for my name, and I will stablish the throne of his kingdom for ever."}], [{"ref": "2 Samuel 12:1-4", "text": "And the LORD sent Nathan unto David. And he came unto him, and said unto him, There were two men in one city; the one rich, and the other poor. The rich man had exceeding many flocks and herds: But the poor man had nothing, save one little ewe lamb, which he had bought and nourished up: and it grew up together with him, and with his children; it did eat of his own meat, and drank of his own cup, and lay in his bosom, and was unto him as a daughter. And there came a traveller unto the rich man, and he spared to take of his own flock and of his own herd, to dress for the wayfaring man that was come unto him; but took the poor man’s lamb, and dressed it for the man that was come to him."}], [{"ref": "2 Samuel 12:7", "text": "And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;"}]]'::jsonb, updated_at = now() where id = 'who-nathan' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 21:2", "text": "There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the sons of Zebedee, and two other of his disciples."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 1:48", "text": "Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee."}], [{"ref": "John 1:47", "text": "Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!"}]]'::jsonb, updated_at = now() where id = 'who-nathanael' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Nehemiah 1:11", "text": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."}, {"ref": "Nehemiah 2:1", "text": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}], [{"ref": "Nehemiah 1:3-4", "text": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire. And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}], [{"ref": "Nehemiah 2:17-18", "text": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach. Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work."}], [{"ref": "Nehemiah 6:15", "text": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}]]'::jsonb, updated_at = now() where id = 'who-nehemiah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 3:1", "text": "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"}], [{"ref": "John 3:2", "text": "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."}], [{"ref": "John 3:7", "text": "Marvel not that I said unto thee, Ye must be born again."}], [{"ref": "John 19:39", "text": "And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight."}]]'::jsonb, updated_at = now() where id = 'who-nicodemus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 7:6", "text": "And Noah was six hundred years old when the flood of waters was upon the earth."}], [{"ref": "Genesis 6:14", "text": "Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."}], [{"ref": "Genesis 6:10", "text": "And Noah begat three sons, Shem, Ham, and Japheth."}], [{"ref": "Hebrews 11:7", "text": "By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith."}]]'::jsonb, updated_at = now() where id = 'who-noah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}], [{"ref": "Galatians 1:13", "text": "For ye have heard of my conversation in time past in the Jews’ religion, how that beyond measure I persecuted the church of God, and wasted it:"}], [{"ref": "Acts 9:3-8", "text": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks. And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do. And the men which journeyed with him stood speechless, hearing a voice, but seeing no man. And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him …"}, {"ref": "Acts 22:11", "text": "And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus."}], [{"ref": "2 Peter 3:15-16", "text": "And account that the longsuffering of our Lord is salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you; As also in all his epistles, speaking in them of these things; in which are some things hard to be understood, which they that are unlearned and unstable wrest, as they do also the other scriptures, unto their own destruction."}]]'::jsonb, updated_at = now() where id = 'who-paul' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Matthew 4:18", "text": "And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers."}], [{"ref": "Matthew 4:19", "text": "And he saith unto them, Follow me, and I will make you fishers of men."}], [{"ref": "Matthew 14:29", "text": "And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus."}], [{"ref": "Matthew 26:75", "text": "And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly."}]]'::jsonb, updated_at = now() where id = 'who-peter' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:43", "text": "The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 14:8", "text": "Philip saith unto him, Lord, shew us the Father, and it sufficeth us."}]]'::jsonb, updated_at = now() where id = 'who-philip_apostle' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 3:1", "text": "Now in the fifteenth year of the reign of Tiberius Cæsar, Pontius Pilate being governor of Judæa, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,"}], [{"ref": "Matthew 27:19", "text": "When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him."}], [{"ref": "John 18:38", "text": "Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault at all."}], [{"ref": "Matthew 27:24", "text": "When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it."}]]'::jsonb, updated_at = now() where id = 'who-pilate' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 18:3", "text": "And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:2", "text": "And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them."}], [{"ref": "Acts 18:1-3", "text": "After these things Paul departed from Athens, and came to Corinth; And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them. And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}]]'::jsonb, updated_at = now() where id = 'who-priscilla' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}], [{"ref": "Genesis 29:20", "text": "And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her."}], [{"ref": "Genesis 35:24", "text": "The sons of Rachel; Joseph, and Benjamin:"}], [{"ref": "Genesis 35:19", "text": "And Rachel died, and was buried in the way to Ephrath, which is Beth-lehem."}]]'::jsonb, updated_at = now() where id = 'who-rachel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:4", "text": "And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were:"}], [{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:17-21", "text": "And the men said unto her, We will be blameless of this thine oath which thou hast made us swear. Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father’s household, home unto thee. And it shall be, that whosoever shall go out of the doors of thy house into the street, his blood shall be upon his head, and we will be guiltless: and whosoever shall be with thee in the house, his blood shall be on our head, if any hand be upon him. And if thou utter this our business, then we will be quit of thine oath which thou hast made us to swear. …"}]]'::jsonb, updated_at = now() where id = 'who-rahab' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Genesis 24:19-20", "text": "And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking. And she hasted, and emptied her pitcher into the trough, and ran again unto the well to draw water, and drew for all his camels."}], [{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 24:67", "text": "And Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother’s death."}], [{"ref": "Genesis 27:6-17", "text": "And Rebekah spake unto Jacob her son, saying, Behold, I heard thy father speak unto Esau thy brother, saying, Bring me venison, and make me savoury meat, that I may eat, and bless thee before the LORD before my death. Now therefore, my son, obey my voice according to that which I command thee. Go now to the flock, and fetch me from thence two good kids of the goats; and I will make them savoury meat for thy father, such as he loveth: And thou shalt bring it to thy father, that he may eat, and that he may bless thee before his death. And Jacob said to Rebekah his mother, Behold, Esau my brother is a hairy man, and I am a smooth man: …"}]]'::jsonb, updated_at = now() where id = 'who-rebekah' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Ruth 1:4", "text": "And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years."}], [{"ref": "Ruth 1:16", "text": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}], [{"ref": "Ruth 2:3", "text": "And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech."}], [{"ref": "Ruth 4:13-17", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son. And the women said unto Naomi, Blessed be the LORD, which hath not left thee this day without a kinsman, that his name may be famous in Israel. And he shall be unto thee a restorer of thy life, and a nourisher of thine old age: for thy daughter in law, which loveth thee, which is better to thee than seven sons, hath born him. And Naomi took the child, and laid it in her bosom, and became nurse unto it. And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."}]]'::jsonb, updated_at = now() where id = 'who-ruth' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Judges 16:17", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man."}], [{"ref": "Judges 14:5-6", "text": "Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him. And the Spirit of the LORD came mightily upon him, and he rent him as he would have rent a kid, and he had nothing in his hand: but he told not his father or his mother what he had done."}], [{"ref": "Judges 16:17-18", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man. And when Delilah saw that he had told her all his heart, she sent and called for the lords of the Philistines, saying, Come up this once, for he hath shewed me all his heart. Then the lords of the Philistines came up unto her, and brought money in their hand."}], [{"ref": "Judges 16:29-30", "text": "And Samson took hold of the two middle pillars upon which the house stood, and on which it was borne up, of the one with his right hand, and of the other with his left. And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life."}]]'::jsonb, updated_at = now() where id = 'who-samson' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 1:9-11", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}, {"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}], [{"ref": "1 Samuel 2:11", "text": "And Elkanah went to Ramah to his house. And the child did minister unto the LORD before Eli the priest."}, {"ref": "1 Samuel 3:1", "text": "And the child Samuel ministered unto the LORD before Eli. And the word of the LORD was precious in those days; there was no open vision."}], [{"ref": "1 Samuel 3:10", "text": "And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth."}], [{"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}, {"ref": "1 Samuel 16:13", "text": "Then Samuel took the horn of oil, and anointed him in the midst of his brethren: and the Spirit of the LORD came upon David from that day forward. So Samuel rose up, and went to Ramah."}]]'::jsonb, updated_at = now() where id = 'who-samuel' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "1 Samuel 9:21", "text": "And Saul answered and said, Am not I a Benjamite, of the smallest of the tribes of Israel? and my family the least of all the families of the tribe of Benjamin? wherefore then speakest thou so to me?"}], [{"ref": "1 Samuel 9:2", "text": "And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people."}], [{"ref": "1 Samuel 9:17", "text": "And when Samuel saw Saul, the LORD said unto him, Behold the man whom I spake to thee of! this same shall reign over my people."}, {"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}], [{"ref": "1 Samuel 28:7-8", "text": "Then said Saul unto his servants, Seek me a woman that hath a familiar spirit, that I may go to her, and enquire of her. And his servants said to him, Behold, there is a woman that hath a familiar spirit at Endor. And Saul disguised himself, and put on other raiment, and he went, and two men with him, and they came to the woman by night: and he said, I pray thee, divine unto me by the familiar spirit, and bring me him up, whom I shall name unto thee."}]]'::jsonb, updated_at = now() where id = 'who-saul' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 15:22", "text": "Then pleased it the apostles and elders, with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas; namely, Judas surnamed Barsabas, and Silas, chief men among the brethren:"}], [{"ref": "Acts 15:39-40", "text": "And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus; And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God."}], [{"ref": "Acts 16:12", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days."}, {"ref": "Acts 16:19", "text": "And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers,"}, {"ref": "Acts 16:22-25", "text": "And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them. And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely: Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks. And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}], [{"ref": "Acts 16:25", "text": "And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}]]'::jsonb, updated_at = now() where id = 'who-silas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 2:25", "text": "And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him."}], [{"ref": "Luke 2:26", "text": "And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord’s Christ."}], [{"ref": "Luke 2:27-28", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law, Then took he him up in his arms, and blessed God, and said,"}], [{"ref": "Luke 2:29", "text": "Lord, now lettest thou thy servant depart in peace, according to thy word:"}]]'::jsonb, updated_at = now() where id = 'who-simeon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 3:9", "text": "Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?"}], [{"ref": "1 Kings 6:14", "text": "So Solomon built the house, and finished it."}], [{"ref": "1 Kings 3:16-27", "text": "Then came there two women, that were harlots, unto the king, and stood before him. And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house. And it came to pass the third day after that I was delivered, that this woman was delivered also: and we were together; there was no stranger with us in the house, save we two in the house. And this woman’s child died in the night; because she overlaid it. And she arose at midnight, and took my son from beside me, while thine handmaid slept, and laid it in her bosom, and laid her dead child in my bosom. And when I rose in the morning to give my child suck, behold, it was dead: but when …"}]]'::jsonb, updated_at = now() where id = 'who-solomon' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Acts 6:2-5", "text": "Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables. Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business. But we will give ourselves continually to prayer, and to the ministry of the word. And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:"}], [{"ref": "Acts 6:8", "text": "And Stephen, full of faith and power, did great wonders and miracles among the people."}], [{"ref": "Acts 7:56", "text": "And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God."}], [{"ref": "Acts 7:58", "text": "And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul."}]]'::jsonb, updated_at = now() where id = 'who-stephen' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:19", "text": "Then the same day at evening, being the first day of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace be unto you."}, {"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:25", "text": "The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe."}], [{"ref": "John 20:28", "text": "And Thomas answered and said unto him, My Lord and my God."}]]'::jsonb, updated_at = now() where id = 'who-thomas' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "2 Timothy 1:5", "text": "When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also."}], [{"ref": "Acts 16:1-3", "text": "Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek: Which was well reported of by the brethren that were at Lystra and Iconium. Him would Paul have to go forth with him; and took and circumcised him because of the Jews which were in those quarters: for they knew all that his father was a Greek."}, {"ref": "1 Timothy 4:12", "text": "Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity."}], [{"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}], [{"ref": "1 Timothy 1:2", "text": "Unto Timothy, my own son in the faith: Grace, mercy, and peace, from God our Father and Jesus Christ our Lord."}, {"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}]]'::jsonb, updated_at = now() where id = 'who-timothy' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 19:2", "text": "And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich."}], [{"ref": "Luke 19:2", "text": "And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich."}], [{"ref": "Luke 19:3", "text": "And he sought to see Jesus who he was; and could not for the press, because he was little of stature."}], [{"ref": "Luke 19:4", "text": "And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way."}]]'::jsonb, updated_at = now() where id = 'who-zacchaeus' and game_mode = 'whoami';
update public.questions set clue_refs = '[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}], [{"ref": "Luke 1:11", "text": "And there appeared unto him an angel of the Lord standing on the right side of the altar of incense."}], [{"ref": "Luke 1:20", "text": "And, behold, thou shalt be dumb, and not able to speak, until the day that these things shall be performed, because thou believest not my words, which shall be fulfilled in their season."}], [{"ref": "Luke 1:63", "text": "And he asked for a writing table, and wrote, saying, His name is John. And they marvelled all."}]]'::jsonb, updated_at = now() where id = 'who-zacharias' and game_mode = 'whoami';
